#pragma once
#include <filesystem>
#include <string>
#include <vector>
#include "config.hpp"

namespace blitz::tidy {
	/** A finding that was left in the file, either because its rule only reports or because it can't be fixed safely. */
	struct report {
		std::string rule;
		uint64_t    line   = 0;
		uint64_t    column = 0;
		uint64_t    length = 0;
		std::string message;
		std::string note;    // Why it was not fixed, if the rule could fix it.
		std::string excerpt; // The source line with the marker.
	};

	struct result {
		std::string                 text;            // The file after the fixes (or as it was, if there were none).
		bool                        changed = false;
		bool                        failed  = false; // The file does not compile, so nothing was changed.
		std::string                 error;
		std::vector<report>         reports;
		std::vector<std::pair<std::string, size_t>> fixed; // How many times each rule was fixed.
		int                         passes = 0;
	};

	/** Fixes the program in `text`, which is the contents of cfg.file (used to find what it includes). */
	result run(std::string const& text, config const& cfg);
} // namespace blitz::tidy
